31	// ModelEntry holds per-model metadata from the v5 manifest.
32	type ModelEntry struct {
33		Family             string                      `yaml:"family,omitempty"`
34		DisplayName        string                      `yaml:"display_name,omitempty"`
35		Status             string                      `yaml:"status,omitempty"`
36		ProviderSystem     string                      `yaml:"provider_system,omitempty"`
37		DeploymentClass    string                      `yaml:"deployment_class,omitempty" json:"deployment_class,omitempty"`
38		PowerProvenance    PowerProvenance             `yaml:"power_provenance,omitempty" json:"power_provenance,omitempty"`
39		CostInputPerM      float64                     `yaml:"cost_input_per_m,omitempty"`
40		CostOutputPerM     float64                     `yaml:"cost_output_per_m,omitempty"`
41		CostCacheReadPerM  float64                     `yaml:"cost_cache_read_per_m,omitempty"`
42		CostCacheWritePerM float64                     `yaml:"cost_cache_write_per_m,omitempty"`
43		CostInputPerMTok   float64                     `yaml:"cost_input_per_mtok,omitempty"`
44		CostOutputPerMTok  float64                     `yaml:"cost_output_per_mtok,omitempty"`
45		SWEBenchVerified   float64                     `yaml:"swe_bench_verified,omitempty"`
46		LiveCodeBench      float64                     `yaml:"live_code_bench,omitempty"`
47		BenchmarkAsOf      string                      `yaml:"benchmark_as_of,omitempty"`
48		OpenRouterID       string                      `yaml:"openrouter_id,omitempty"`
49		OpenRouterRefID    string                      `yaml:"openrouter_ref_id,omitempty"`
50		Surfaces           map[string]string           `yaml:"surfaces,omitempty"`
51		SpeedTokensPerSec  float64                     `yaml:"speed_tokens_per_sec,omitempty"`
52		ContextWindow      int                         `yaml:"context_window,omitempty"`
53		Power              int                         `yaml:"power,omitempty" json:"power,omitempty"`
54		ExactPinOnly       bool                        `yaml:"exact_pin_only,omitempty" json:"exact_pin_only,omitempty"`
55		NoTools            bool                        `yaml:"no_tools,omitempty"`
56		ReasoningDefault   reasoning.Reasoning         `yaml:"reasoning_default,omitempty"`
57		ReasoningMaxTokens int                         `yaml:"reasoning_max_tokens,omitempty"`
58		ReasoningBudgets   map[reasoning.Reasoning]int `yaml:"reasoning_budgets,omitempty"`
59		ReasoningLevels    []string                    `yaml:"reasoning_levels,omitempty"`
60		ReasoningControl   string                      `yaml:"reasoning_control,omitempty"`
61		ReasoningWire      string                      `yaml:"reasoning_wire,omitempty"`
62		// SamplingControl declares whether catalog sampling_profiles reach the
63		// wire for runs that resolve to this model. See ADR-007 §4.
64		//   client_settable (default) — provider honors all five sampler fields.
65		//   harness_pinned             — wrapped harness pins samplers internally;
66		//                                 the resolver short-circuits to a
67		//                                 zero-value bundle.
68		//   partial                    — provider honors a subset (reserved; not
69		//                                 enforced in v1).
70		SamplingControl string `yaml:"sampling_control,omitempty"`
71	}
