102	type manifest struct {
103		Version        int                      `yaml:"version"`
104		GeneratedAt    string                   `yaml:"generated_at"`
105		CatalogVersion string                   `yaml:"catalog_version,omitempty"`
106		Models         map[string]ModelEntry    `yaml:"models,omitempty"`
107		Policies       map[string]policyEntry   `yaml:"policies,omitempty"`
108		Providers      map[string]providerEntry `yaml:"providers,omitempty"`
109		// SamplingProfiles is a map from profile name (e.g., "code") to a named
110		// bundle of sampling-parameter overrides. Profile bundles are the L1
111		// layer of the resolution chain; see ADR-007.
112		SamplingProfiles map[string]sampling.Profile `yaml:"sampling_profiles,omitempty"`
113	}
