128	// Default loads the embedded default catalog snapshot.
129	func Default() (*Catalog, error) {
130		return Load(LoadOptions{})
131	}
132	
133	// Load loads a catalog from an external manifest or falls back to the embedded snapshot.
134	func Load(opts LoadOptions) (*Catalog, error) {
135		data := embeddedManifest
136		source := "embedded"
137	
138		if opts.ManifestPath != "" {
139			externalData, err := os.ReadFile(opts.ManifestPath)
140			if err != nil {
141				if opts.RequireExternal {
142					return nil, fmt.Errorf("modelcatalog: read manifest %s: %w", opts.ManifestPath, err)
143				}
144			} else {
145				data = externalData
146				source = opts.ManifestPath
147			}
148		}
149	
150		return loadManifest(data, source)
151	}
152	
153	func loadManifest(data []byte, source string) (*Catalog, error) {
154		var m manifest
155		if err := yaml.Unmarshal(data, &m); err != nil {
156			return nil, fmt.Errorf("modelcatalog: parse manifest %s: %w", source, err)
157		}
158		if err := validateManifest(m); err != nil {
159			return nil, fmt.Errorf("modelcatalog: validate manifest %s: %w", source, err)
160		}
161		return &Catalog{
162			manifest:    m,
163			manifestSrc: source,
164		}, nil
165	}
166	
167	func validateManifest(m manifest) error {
168		if m.Version != maxSchemaVersion {
169			return fmt.Errorf("manifest schema v%d required (got v%d); see ADR-009 for v0.11 schema redesign", maxSchemaVersion, m.Version)
170		}
171		if len(m.Policies) == 0 {
172			return fmt.Errorf("policies must not be empty")
173		}
174		if _, ok := m.Policies["default"]; !ok {
175			return fmt.Errorf("default policy must be defined")
176		}
177	
178		policyNames := make([]string, 0, len(m.Policies))
179		for name := range m.Policies {
180			policyNames = append(policyNames, name)
181		}
182		sort.Strings(policyNames)
183		for _, name := range policyNames {
184			entry := m.Policies[name]
185			if strings.TrimSpace(name) == "" {
186				return fmt.Errorf("policy name must not be empty")
187			}
188			if entry.MinPower <= 0 {
189				return fmt.Errorf("policy %q min_power must be > 0", name)
190			}
191			if entry.MaxPower <= 0 {
192				return fmt.Errorf("policy %q max_power must be > 0", name)
193			}
194			if entry.MinPower > entry.MaxPower {
195				return fmt.Errorf("policy %q min_power must be <= max_power", name)
196			}
197			if entry.MaxPower > 10 {
198				return fmt.Errorf("policy %q max_power must be <= 10", name)
199			}
200			for _, requirement := range entry.Require {
201				if !knownPolicyRequirement(requirement) {
202					return fmt.Errorf("policy %q has unknown require invariant %q", name, requirement)
203				}
204			}
205		}
206	
207		providerNames := make([]string, 0, len(m.Providers))
208		for name := range m.Providers {
209			providerNames = append(providerNames, name)
210		}
211		sort.Strings(providerNames)
212		for _, name := range providerNames {
213			entry := m.Providers[name]
214			if strings.TrimSpace(name) == "" {
215				return fmt.Errorf("provider name must not be empty")
216			}
217			if strings.TrimSpace(entry.Type) == "" {
218				return fmt.Errorf("provider %q must define type", name)
219			}
220			if entry.Billing != "" && !knownBillingModel(BillingModel(entry.Billing)) {
221				return fmt.Errorf("provider %q has invalid billing %q", name, entry.Billing)
222			}
223			if !knownProviderSystem(entry.Type) && strings.TrimSpace(entry.Billing) == "" {
224				return fmt.Errorf("provider %q type %q requires explicit billing field", name, entry.Type)
225			}
226		}
227	
228		for modelID, model := range m.Models {
229			if strings.TrimSpace(modelID) == "" {
230				return fmt.Errorf("model ID must not be empty")
231			}
232			status := normalizedStatus(model.Status)
233			switch status {
234			case statusActive, statusDeprecated, statusStale:
235			default:
236				return fmt.Errorf("model %q has invalid status %q", modelID, model.Status)
237			}
238			if model.CostInputPerM < 0 || model.CostInputPerMTok < 0 {
239				return fmt.Errorf("model %q cost_input_per_m must be >= 0", modelID)
240			}
241			if model.CostOutputPerM < 0 || model.CostOutputPerMTok < 0 {
242				return fmt.Errorf("model %q cost_output_per_m must be >= 0", modelID)
243			}
244			if model.CostCacheReadPerM < 0 {
245				return fmt.Errorf("model %q cost_cache_read_per_m must be >= 0", modelID)
246			}
247			if model.CostCacheWritePerM < 0 {
248				return fmt.Errorf("model %q cost_cache_write_per_m must be >= 0", modelID)
249			}
250			if model.ContextWindow < 0 {
251				return fmt.Errorf("model %q context_window must be >= 0", modelID)
252			}
253			if model.Power < 0 {
254				return fmt.Errorf("model %q power must be >= 0", modelID)
255			}
256			if model.Power > 10 {
257				return fmt.Errorf("model %q power must be <= 10", modelID)
258			}
259			if model.ReasoningMaxTokens < 0 {
260				return fmt.Errorf("model %q reasoning_max_tokens must be >= 0", modelID)
261			}
262			for level, budget := range model.ReasoningBudgets {
263				if budget < 0 {
264					return fmt.Errorf("model %q reasoning_budgets %q must be >= 0", modelID, level)
265				}
266				if model.ReasoningMaxTokens > 0 && budget > model.ReasoningMaxTokens {
267					return fmt.Errorf("model %q reasoning_budgets %q exceeds reasoning_max_tokens", modelID, level)
268				}
269			}
270			switch model.ReasoningDefault {
271			case "", reasoning.ReasoningOff, reasoning.ReasoningLow, reasoning.ReasoningMedium, reasoning.ReasoningHigh, reasoning.ReasoningMax, reasoning.ReasoningXHigh:
272			default:
273				return fmt.Errorf("model %q has invalid reasoning_default %q", modelID, model.ReasoningDefault)
274			}
275			switch model.ReasoningControl {
276			case "", ReasoningControlTunable, ReasoningControlFixed, ReasoningControlNone:
277			default:
278				return fmt.Errorf("model %q has invalid reasoning_control %q (must be one of tunable, fixed, none)", modelID, model.ReasoningControl)
279			}
280			switch model.ReasoningWire {
281			case "", ReasoningWireProvider, ReasoningWireModelID, ReasoningWireNone:
282			default:
283				return fmt.Errorf("model %q has invalid reasoning_wire %q (must be one of provider, model_id, none)", modelID, model.ReasoningWire)
284			}
285			switch model.SamplingControl {
286			case "", SamplingControlClientSettable, SamplingControlHarnessPinned, SamplingControlPartial:
287			default:
288				return fmt.Errorf("model %q has invalid sampling_control %q (must be one of client_settable, harness_pinned, partial)", modelID, model.SamplingControl)
289			}
290		}
291	
292		return nil
293	}
294	
295	func knownPolicyRequirement(requirement string) bool {
296		switch strings.TrimSpace(requirement) {
297		case "no_remote":
298			return true
299		default:
300			return false
301		}
302	}
303	
304	func normalizedStatus(status string) string {
305		status = strings.ToLower(strings.TrimSpace(status))
306		if status == "" {
307			return statusActive
308		}
309		return status
310	}
